% Define initial parameters (feel free to change values)
theta0 = pi/6; % initial angle (in radians)
omega0 = 0; % initial angular velocity (in radians/second)
L = 1; % length of the rod (in meters)
g = 9.81; % acceleration due to gravity (in m/s^2)
b = 0.1; % damping coefficient (in kg/s)
tspan = [0, 10]; % time span (in seconds)

% Set up the differential equation
odefun = @(t, y) [y(2); -(g/L)*sin(y(1))- b*y(2)];

% Solve the differential equation
[t, sol] = ode45(odefun, tspan, [theta0; omega0]);

% Plot the motion of the pendulum
theta = sol(:, 1);
x = L*sin(theta);
y = -L*cos(theta);
figure();
plot(x, y);
xlabel('x position (m)');
ylabel('y position (m)');
title('Simple Pendulum Motion');
axis equal;

% Calculate and display the period and frequency
