"""A program that generates a list of prime numbers within a given integer range."""

import sys


def is_prime(num):
    """Check if a given integer is a prime number."""
    if num < 2:
        return False
    for I in range(2, int(num ** 0.5) + 1):
        if num % I == 0:
            return False
    return True


def generate_primes(start, end):
    """Generate a list of prime numbers within a given integer range."""
    primes = []
    for num in range(start, end + 1):
        if is_prime(num):
            primes.append(num)
    return primes


def main():
    """Main function to handle user input and program logic."""
    try:
        start = int(sys.argv[1])
        end = int(sys.argv[2])
        if start >= end:
            raise ValueError("Invalid range.")
    except (ValueError, IndexError):
        print("USAGE: python prime_numbers.py <start> <end>")
        print("<start> and <end> should be positive integers with <start> < <end>.")
        return

    primes = generate_primes(start, end)
    print(f"Generated {len(primes)} prime numbers between {start} and {end}:")
    for prime in primes:
        print(prime)


if __name__ == "__main__":
    main()

