    let mut mount = Mount::new();

    // Serve static files from the `public` directory
    mount.mount("/", Static::new(Path::new("public")).gzip(GzipWriter::new()));

    // Start serving requests
    Iron::new(mount).http("localhost:8080").unwrap();
